import Foundation

/// The GC/Wii titles GameBanana has mods for, keyed both ways: GameBanana game id and the
/// Dolphin/GameTDB game ids of the same title. Generated by `Tools/mods/gen_mod_game_table.py`.
struct ModGameTable {
  struct Entry: Decodable, Hashable, Identifiable {
    let bananaID: Int
    let name: String
    let iconURL: URL?
    let gameIDs: [String]

    var id: Int { bananaID }

    init(bananaID: Int, name: String, iconURL: URL? = nil, gameIDs: [String]) {
      self.bananaID = bananaID
      self.name = name
      self.iconURL = iconURL
      self.gameIDs = gameIDs
    }

    init(from decoder: Decoder) throws {
      enum Keys: String, CodingKey { case bananaID, name, iconURL, gameIDs }
      let c = try decoder.container(keyedBy: Keys.self)
      bananaID = try c.decode(Int.self, forKey: .bananaID)
      name = try c.decode(String.self, forKey: .name)
      iconURL = (try? c.decodeIfPresent(String.self, forKey: .iconURL)).flatMap { $0.isEmpty ? nil : URL(string: $0) }
      gameIDs = try c.decode([String].self, forKey: .gameIDs)
    }
  }

  private struct File: Decodable {
    let games: [Entry]
  }

  /// Length of the title code a Dolphin game id starts with. Regions and revisions of one title
  /// share it (`RMCE01`, `RMCP01`), and so do Dolphin custom-game ids (`RMCE60`).
  private static let titleCodeLength = 3

  let entries: [Entry]
  private let byTitleCode: [String: Entry]
  private let byBananaID: [Int: Entry]

  init(entries: [Entry]) {
    self.entries = entries
    var titleCodes: [String: Entry] = [:]
    for entry in entries {
      for id in entry.gameIDs { titleCodes[Self.titleCode(of: id)] = entry }
    }
    byTitleCode = titleCodes
    byBananaID = Dictionary(entries.map { ($0.bananaID, $0) }, uniquingKeysWith: { first, _ in first })
  }

  init(jsonData: Data) throws {
    self.init(entries: try JSONDecoder().decode(File.self, from: jsonData).games)
  }

  /// The table bundled with the app.
  static let bundled: ModGameTable = {
    guard let url = Bundle.main.url(forResource: "ModGameTable", withExtension: "json"),
          let data = try? Data(contentsOf: url),
          let table = try? ModGameTable(jsonData: data) else { return ModGameTable(entries: []) }
    return table
  }()

  func entry(forBananaID id: Int) -> Entry? { byBananaID[id] }

  /// The table entry for a library game id (`GALE01`), matched on its title code.
  func entry(forGameID gameID: String) -> Entry? {
    guard gameID.count >= Self.titleCodeLength else { return nil }
    return byTitleCode[Self.titleCode(of: gameID)]
  }

  private static func titleCode(of gameID: String) -> String {
    String(gameID.uppercased().prefix(titleCodeLength))
  }
}
